import{_ as n,C as s,o,c as r,j as i,E as l,a as e,a3 as d}from"./chunks/framework.C6R8kWFE.js";const v=JSON.parse(`{"title":"5-hafta","description":"","frontmatter":{"title":"5-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf","link":"/9-sinf/"},"n":5,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":13,"title":"UI kit va dizayn tizimi tushunchasi","lead":"Bitta ilovaning 10 ta ekranida 10 xil ko'k tugma bo'lsa, foydalanuvchi buni darhol «tartibsizlik» deb sezadi. Katta kompaniyalar bu muammoni UI kit va dizayn tizimlari bilan hal qiladi. Bugun ular nima ekanini bilib olasiz va o'zingizning birinchi mini UI kitingizni yaratasiz.","link":"/9-sinf/hafta-05/dars-1","slide":"/slaydlar/9-sinf/hafta-05/dars-1.html","test":"/slaydlar/9-sinf/hafta-05/dars-1-test.html"},{"g":14,"title":"Mashhur UI kitlar: HIG, Ant Design, Bootstrap, Figma UI Kit, Material UI","lead":"iPhone ilovalari bir-biriga o'xshaydi, Google ilovalari ham — o'zaro. Sababi oddiy: ular bir xil UI kit va qoidalar asosida yaratilgan. Bugun dunyodagi 5 ta eng mashhur UI kit bilan tanishasiz va o'z loyihangiz uchun to'g'risini tanlashni o'rganasiz.","link":"/9-sinf/hafta-05/dars-2","slide":"/slaydlar/9-sinf/hafta-05/dars-2.html","test":"/slaydlar/9-sinf/hafta-05/dars-2-test.html"},{"g":15,"title":"UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli","lead":"Nazariya tugadi — endi qo'l ishi! Bugun Figma'da haqiqiy elektron kutubxona sahifasining eng muhim ikki qismini yasaysiz: qidiruvli header va kategoriyalar paneli. Har bir piksel, rang va burchak aniq qiymat bilan beriladi.","link":"/9-sinf/hafta-05/dars-3","slide":"/slaydlar/9-sinf/hafta-05/dars-3.html","test":"/slaydlar/9-sinf/hafta-05/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"9-sinf/hafta-05/index.md","filePath":"9-sinf/hafta-05/index.md"}`),h={name:"9-sinf/hafta-05/index.md"},u={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function m(y,a,k,f,b,c){const t=s("Icon");return o(),r("div",null,[i("div",u,[i("h2",g,[l(t,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–40 daqiqa. Barcha ishlarni bitta «E-kutubxona» Figma faylida (alohida sahifalarda) saqlang. Topshirish: keyingi dars boshida mentorga Figma havolasini (view huquqi bilan) ko&#39;rsating.</p><h3 id="_13-dars-uchun-ui-kit-va-dizayn-tizimi-tushunchasi" tabindex="-1">13-dars uchun (UI kit va dizayn tizimi tushunchasi) <a class="header-anchor" href="#_13-dars-uchun-ui-kit-va-dizayn-tizimi-tushunchasi" aria-label="Permalink to &quot;13-dars uchun (UI kit va dizayn tizimi tushunchasi)&quot;">​</a></h3><p><strong>1-topshiriq: «E-kutubxona UI kit sahifasi»</strong></p><ol><li>13-darsda boshlangan <code>UI Kit</code> sahifasini oching (Colors, Typography, Buttons).</li><li><strong>Inputs</strong> bo&#39;limini qo&#39;shing: oddiy (default), fokus (focus) va xato (error) holatidagi 3 ta matn maydoni (320 × 48, radius 8).</li><li>Barcha elementlarda faqat <strong>Color styles</strong> va <strong>Text styles</strong>&#39;dan foydalaning — HEX qiymatni qo&#39;lda yozmang.</li><li>Sahifa yon tomoniga token jadvalini matn sifatida yozing: 5 rang, 3 matn uslubi, 4 bo&#39;shliq (8, 16, 24, 32).</li></ol><p><strong>Kutiladigan natija:</strong> 4 bo&#39;limli (Colors, Typography, Buttons, Inputs) UI kit sahifasi va token jadvali; Primary rang o&#39;zgartirilganda tugma ham yangilanadi.</p><hr><h3 id="_14-dars-uchun-mashhur-ui-kitlar" tabindex="-1">14-dars uchun (Mashhur UI kitlar) <a class="header-anchor" href="#_14-dars-uchun-mashhur-ui-kitlar" aria-label="Permalink to &quot;14-dars uchun (Mashhur UI kitlar)&quot;">​</a></h3><p><strong>2-topshiriq: «Tayyor kitdan o&#39;rganamiz»</strong></p><ol><li>Figma <strong>Community</strong>&#39;dan bitta UI kitni oching (Material 3 Design Kit, iOS UI Kit, Ant Design yoki Bootstrap).</li><li>Undan 5 ta komponentni nusxalang: button, input, checkbox, card, navbar (yoki tabs).</li><li>Ularni «E-kutubxona» stillari (13-dars) bilan qayta bo&#39;yang.</li><li>3–4 jumlali izoh yozing: kit nimasi bilan yoqdi / yoqmadi, «E-kutubxona» uchun mosmi va nega.</li></ol><p><strong>Kutiladigan natija:</strong> <code>Kit tahlili</code> frame&#39;ida 5 ta qayta bo&#39;yalgan komponent va asoslangan izoh.</p><hr><h3 id="_15-dars-uchun-ui-kit-amaliyoti-header-va-kategoriya-paneli" tabindex="-1">15-dars uchun (UI kit amaliyoti: header va kategoriya paneli) <a class="header-anchor" href="#_15-dars-uchun-ui-kit-amaliyoti-header-va-kategoriya-paneli" aria-label="Permalink to &quot;15-dars uchun (UI kit amaliyoti: header va kategoriya paneli)&quot;">​</a></h3><p><strong>3-topshiriq: «E-kutubxona sahifasini to&#39;ldirish»</strong></p><ol><li>Darsda yaratilgan header va kategoriya paneliga asosiy menyu qo&#39;shing: «Bosh sahifa», «Yangi kitoblar», «Mualliflar», «Aloqa».</li><li>«Barcha kitoblar» tugmasini va kontent qismida banner joyini (Rectangle) qo&#39;shing.</li><li>Yagona uslub: bir xil ranglar (stillar), Inter shrifti, bir xil radius, 8-point grid oraliqlari; red guides bilan masofalarni tekshiring.</li><li>Qidiruv blokini (<code>Search/Default</code>) va tugmani komponentga aylantiring.</li></ol><p><strong>Kutiladigan natija:</strong> header, menyu, kategoriya paneli, tugma va banner joyidan iborat, yagona uslubdagi sahifa qismi; Assets&#39;da kamida 2 ta komponent.</p>',15))])])}const z=n(h,[["render",m]]);export{v as __pageData,z as default};
